const ROLE_ACTIONS=['read','collect','research','alert','ai','configure','users'];
async function roleAdd(){openModal(`<h3>New custom role</h3><form onsubmit="roleSave(event)">${field('Name (letters, digits, - _)','name')}${ROLE_ACTIONS.map(a=>`<label class="form-check"><input type="checkbox" name="p_${a}" class="form-check-input"> ${a}</label>`).join('')}<div class="btn-list mt-2"><button class="btn btn-primary">Create</button><button type="button" class="btn" onclick="closeModal()">Cancel</button></div></form>`);}
