async function doLogin(e){e.preventDefault();const v=formVals(e.target);try{const r=await post('/api/v1/auth/login',{email:v.email,password:v.password});$('#tok').value=r.token;closeModal();toast('Logged in as '+r.email);load();}catch(err){toast('Login failed: '+String(err).slice(0,200))}}
async function doLogout(){try{await post('/api/v1/auth/logout',{});}catch(e){}$('#tok').value='';toast('Logged out');load();}
async function dashCharts(){try{
const day=86400;const now=Date.now()/1000;const days=[];
for(let i=13;i>=0;i--){const d=new Date((now-i*day)*1000);days.push(d.toISOString().slice(0,10));}
const jobs=(await api('/api/v1/jobs?size=100')).items||[];
const byDay={};jobs.forEach(j=>{let t=j.created_at;if(typeof t==='string'){t=Date.parse(t)/1000;}if(!t)return;const k=new Date(t*1000).toISOString().slice(0,10);byDay[k]=(byDay[k]||0)+1;});
const el1=$('#chJobs');if(el1)el1.innerHTML=barChart(days.map(k=>[k.slice(5),byDay[k]||0]));
const alerts=(await api('/api/v1/alerts?size=100')).items||[];
const bySev={};alerts.forEach(a=>{const s=(a.severity||'info');bySev[s]=(bySev[s]||0)+1;});
const el2=$('#chAlerts');if(el2)el2.innerHTML=barChart(Object.entries(bySev));
const fnd=(await api('/api/v1/findings?size=100')).items||[];
const byF={};fnd.forEach(f=>{const s=(f.severity||'info');byF[s]=(byF[s]||0)+1;});
const el3=$('#chFind');if(el3)el3.innerHTML=barChart(Object.entries(byF));
}catch(e){}}
